from typing import List

def process_strings(s: str, t: str) -> List[int]:
    positions = []
    s_index = 0

    for t_index in range(len(t)):
        if s_index < len(s) and t[t_index] == s[s_index]:
            positions.append(t_index + 1)
            s_index += 1

    return positions
